 9: ["..####..", ".#....#.", ".#....#.", "..#####.", "......#.", "......#.", ".....#..", "..###..."],
}
TEMPL = np.array([[[c == "#" for c in row] for row in GLYPHS[d]] for d in range(10)], dtype=float)

def make_digits(n, seed=0):
    """Synthetic 8x8 'handwritten' digits: shifted, scaled, noisy. Returns (images uint8 (n, 8, 8), labels (n,))."""
    rng = np.random.default_rng(seed)
    y = rng.integers(0, 10, n)
    imgs = np.empty((n, 8, 8))
    for i, d in enumerate(y):
        im = np.roll(TEMPL[d], (rng.integers(-1, 2), rng.integers(-1, 2)), axis=(0, 1))
        im = im * rng.uniform(0.6, 1.0) + rng.normal(0, 0.2, (8, 8))
        imgs[i] = np.clip(im, 0, 1)
    return (imgs * 255).astype(np.uint8), y

def prepare(images):
    """(N, H, W) uint8 -> (N, H*W) floats in [0, 1]."""
    return images.reshape(len(images), -1).astype(float) / 255.0

def one_hot(y, k=10):
    Y = np.zeros((len(y), k))
    Y[np.arange(len(y)), y] = 1.0
    return Y

def split(X, Y, val_frac=0.2, seed=0):
    idx = np.random.default_rng(seed).permutation(len(X))
    n_val = int(len(X) * val_frac)
    va, tr = idx[:n_val], idx[n_val:]
    return X[tr], Y[tr], X[va], Y[va]

def init_params(rng, n_in, n_hidden, n_out):
    """He initialisation for the ReLU layer."""
    return {"W1": rng.normal(0, np.sqrt(2 / n_in), (n_in, n_hidden)), "b1": np.zeros(n_hidden),
            "W2": rng.normal(0, np.sqrt(2 / n_hidden), (n_hidden, n_out)), "b2": np.zeros(n_out)}

def forward(X, p):
    """Returns probabilities (N, 10) and a cache (X, h_pre, h) for backward."""
    # TODO 1: h_pre = X @ W1 + b1; h = ReLU(h_pre)
